"use client";

import { useReducedMotion } from "motion/react";
import { type ComponentPropsWithoutRef, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a paragraph whose words turn from muted to full colour in reading order. */
export type ReadAlongProps = Omit<ComponentPropsWithoutRef<"p">, "children"> & {
  text: string;
  /**
   * From 0 to 1. When set, the words follow it, so the paragraph can track
   * audio or scroll. Leave it out and the words advance at reading pace.
   */
  progress?: number;
  /** Reading pace when `progress` is not set. */
  wordsPerMinute?: number;
  /** Set it to false to hold the pace on the current word. It does nothing when `progress` is set. */
  playing?: boolean;
  /** Gives the current word a soft background. */
  highlight?: boolean;
  /** Runs when the pace reaches the last word. It does not run when `progress` is set. */
  onDone?: () => void;
};

/**
 * Lights a paragraph word by word, at reading pace or tied to `progress`.
 * Unread words stay readable in the muted colour, so nobody has to wait for
 * the pace. The words are real text, so screen readers read the paragraph
 * once. With reduced motion a paced paragraph is shown fully lit at once; one
 * tied to `progress` still follows it, without the fade.
 */
export function ReadAlong({
  text,
  progress,
  wordsPerMinute = 220,
  playing = true,
  highlight = true,
  onDone,
  className,
  ...paragraphProps
}: ReadAlongProps) {
  const reduceMotion = useReducedMotion();
  const words = text.split(/\s+/).filter(Boolean);
  const count = words.length;
  const controlled = progress !== undefined;
  // The pace belongs to one text. A new text starts again from its first word.
  const [pace, setPace] = useState({ text, index: 0 });
  if (pace.text !== text) setPace({ text, index: 0 });
  const done = useRef(onDone);

  useEffect(() => {
    done.current = onDone;
  }, [onDone]);

  const finished = pace.index >= count;
  const pacing = !controlled && !reduceMotion && playing && !finished;

  useEffect(() => {
    if (!pacing) return;
    const timer = window.setInterval(
      () => setPace((current) => ({ ...current, index: current.index + 1 })),
      60000 / Math.max(wordsPerMinute, 1),
    );
    return () => window.clearInterval(timer);
  }, [pacing, wordsPerMinute]);

  useEffect(() => {
    // Reduced motion lights the whole paragraph at once, so it is done at once too.
    if (!controlled && count > 0 && (finished || reduceMotion)) done.current?.();
  }, [controlled, finished, count, reduceMotion]);

  // `current` is the word being read. Everything before it is read.
  let current = pace.index;
  if (controlled) current = Math.floor(Math.min(Math.max(progress, 0), 1) * count);
  else if (reduceMotion) current = count;

  return (
    <p {...paragraphProps} className={cn("text-foreground", className)}>
      {words.map((word, index) => {
        const state = index < current ? "read" : index === current ? "current" : "unread";
        return (
          <span key={`${word}-${index}`}>
            <span
              data-state={state}
              className={cn(
                // The padding and the margin cancel out, so the highlight has room and no word moves.
                "-mx-0.5 rounded-sm px-0.5 motion-safe:transition-colors motion-safe:duration-200 motion-safe:ease-out",
                state === "unread" && "text-muted-foreground",
                state === "current" && highlight && "bg-primary/15",
              )}
            >
              {word}
            </span>
            {index < count - 1 ? " " : null}
          </span>
        );
      })}
    </p>
  );
}
